from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.errors import BillingError
from ledgerly.models import Payment

T0 = datetime(2026, 10, 1, tzinfo=timezone.utc)
def pay(amount="5000.00", status="captured", refunded="0.00"):
    return Payment("p", "i", Decimal(amount), status=status, created_at=T0, captured_at=T0, refunded_amount=Decimal(refunded))

# at threshold: no approval needed
p = pay(); outage_refund(p, Decimal("1000.00"), T0); print("at threshold ok", p.refunded_amount)
# above threshold without approval
try: outage_refund(pay(), Decimal("1000.01"), T0)
except BillingError as e: print("above no approval:", e.code)
# above threshold with approval
p = pay(); outage_refund(p, Decimal("1000.01"), T0, approved_by="mgr"); print("approved ok", p.refunded_amount)
# full refund sets status
p = pay("80.00"); outage_refund(p, Decimal("80.00"), T0); print("full:", p.status, p.refunded_amount)
# partial keeps captured
p = pay("80.00"); outage_refund(p, Decimal("8.00"), T0); print("partial:", p.status, p.refunded_amount)
# non-positive
try: outage_refund(pay(), Decimal("0"), T0)
except BillingError as e: print("zero:", e.code)
# exceeds captured
try: outage_refund(pay("80.00"), Decimal("80.01"), T0)
except BillingError as e: print("exceeds:", e.code)
# not captured
try: outage_refund(pay(status="authorized"), Decimal("1"), T0)
except BillingError as e: print("state:", e.code)
EOF"}

